from PIL import Image
import numpy as np, heapq, math
im=np.array(Image.open('/app/target.png').convert('RGB'))
a=(im[:,:,0]<100)
y0,y1,x0,x1=200,815,260,790
m=np.pad(a[y0:y1,x0:x1],1).astype(np.uint8)
def sh(a,dy,dx):
 p=np.pad(a,1);return p[1+dy:1+dy+a.shape[0],1+dx:1+dx+a.shape[1]]
for it in range(100):
 ch=0
 for st in (0,1):
  p2=sh(m,-1,0);p3=sh(m,-1,1);p4=sh(m,0,1);p5=sh(m,1,1);p6=sh(m,1,0);p7=sh(m,1,-1);p8=sh(m,0,-1);p9=sh(m,-1,-1)
  n=p2+p3+p4+p5+p6+p7+p8+p9
  t=sum([((p2==0)&(p3==1)),((p3==0)&(p4==1)),((p4==0)&(p5==1)),((p5==0)&(p6==1)),((p6==0)&(p7==1)),((p7==0)&(p8==1)),((p8==0)&(p9==1)),((p9==0)&(p2==1))])
  if st==0:c1=(p2*p4*p6)==0;c2=(p4*p6*p8)==0
  else:c1=(p2*p4*p8)==0;c2=(p2*p6*p8)==0
  r=(m==1)&(n>=2)&(n<=6)&(t==1)&c1&c2;ch+=int(r.sum());m[r]=0
 if ch==0:break
sk=m[1:-1,1:-1].astype(bool)
coords=np.argwhere(sk); pointset=set((int(x+x0),int(y+y0)) for y,x in coords)
# build neighbor graph in absolute coordinates
adj={p:[] for p in pointset}
for x,y in pointset:
 for dx in (-1,0,1):
  for dy in (-1,0,1):
   if not(dx or dy):continue
   q=(x+dx,y+dy)
   if q in pointset:adj[(x,y)].append((q,math.sqrt(2) if dx and dy else 1.0))
def near(pt):return min(pointset,key=lambda q:(q[0]-pt[0])**2+(q[1]-pt[1])**2)
def route(a,b):
 s=near(a);g=near(b);dist={s:0.};prev={};heap=[(0.,s)]
 while heap:
  d,u=heapq.heappop(heap)
  if d!=dist[u]:continue
  if u==g:break
  for v,w in adj[u]:
   nd=d+w
   if nd<dist.get(v,1e9):dist[v]=nd;prev[v]=u;heapq.heappush(heap,(nd,v))
 path=[g]
 while path[-1]!=s:path.append(prev[path[-1]])
 path.reverse();return path,s,g,dist[g]
def sparse(path,step=20):
 out=[path[0]];last=path[0];acc=0.
 for p,q in zip(path[:-1],path[1:]):
  acc+=math.hypot(q[0]-p[0],q[1]-p[1])
  if acc>=step:out.append(q);acc=0
 if out[-1]!=path[-1]:out.append(path[-1])
 return out
strokes=[((368,236),(654,226),'top'),((393,257),(390,515),'left vertical'),((522,250),(525,487),'middle vertical'),((459,342),(608,320),'bar1'),((453,424),(611,399),'bar2'),((390,515),(590,719),'bottom'),((304,575),(292,672),'dot1'),((382,590),(401,636),'dot2'),((457,570),(487,616),'dot3'),((551,547),(590,599),'dot4')]
for a,b,n in strokes:
 path,s,g,L=route(a,b)
 print(n,'nearest',s,g,'len',round(L,1),'sparse',sparse(path,24))
